        return []

    sorted_slots = sorted(slots, key=lambda x: x[0])
    merged = [sorted_slots[0]]

    for current_slot in sorted_slots[1:]:
        last_slot = merged[-1]
        if current_slot[0] <= last_slot[1]:
            merged[-1] = [min(last_slot[0], current_slot[0]), max(last_slot[1], current_slot[1])]
        else:
            merged.append(current_slot)

    return merged
